private void maybeNotifyInternalError(String name, Exception cause) {
  String message = "Internal error in " + name;
  Log.e(TAG, message, cause);
  try {
    for (int i = 0; i < adPlaybackState.adGroupCount; i++) {
      adPlaybackState = adPlaybackState.withSkippedAdGroup(i);
    }
    updateAdPlaybackState();
    if (eventListener != null) {
      eventListener.onAdLoadError(AdLoadException.createForUnexpected(new RuntimeException(message, cause)), getAdsDataSpec(adTagUri));
    }
  } catch (RuntimeException e) {
    Log.e(TAG, "RuntimeException occurred while processing ad playback state", e);
  }
}
